<?php
namespace App\Http\Controllers; use App\Models\{Attendance,SchoolClass}; use App\Exports\AttendanceExport; use Barryvdh\DomPDF\Facade\Pdf; use Illuminate\Http\Request; use Maatwebsite\Excel\Facades\Excel;
class ReportController extends Controller{public function index(Request $r){$query=$this->query($r);return view('reports.index',['rows'=>$query->paginate(20)->withQueryString(),'classes'=>SchoolClass::all()]);}public function excel(Request $r){return Excel::download(new AttendanceExport($this->query($r)->get()),'laporan-absensi.xlsx');}public function pdf(Request $r){return Pdf::loadView('reports.pdf',['rows'=>$this->query($r)->get()])->setPaper('a4','landscape')->download('laporan-absensi.pdf');}private function query(Request $r){return Attendance::with(['student.schoolClass','recorder'])->when($r->user()->isWali(),fn($q)=>$q->whereHas('student',fn($s)=>$s->where('class_id',$r->user()->class_id)))->when(!$r->user()->isWali()&&$r->class_id,fn($q)=>$q->whereHas('student',fn($s)=>$s->where('class_id',$r->class_id)))->when($r->start_date,fn($q,$v)=>$q->whereDate('attendance_date','>=',$v))->when($r->end_date,fn($q,$v)=>$q->whereDate('attendance_date','<=',$v))->when($r->status,fn($q,$v)=>$q->where('status',$v))->latest('attendance_date');}}
